  printYieldExpression(printer: any, node: any) {
    this.printYieldOrAwait(printer, node, "yield");
  }

  printAwaitExpression(printer: any, node: any) {
    this.printYieldOrAwait(printer, node, "await");
  }

  printEmptyStatement(printer: any) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "EmptyStatement";
    try {
      printer.semicolon(true);
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printExpressionStatement(printer: any, node: t.ExpressionStatement) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "ExpressionStatement";
    try {
      printer.print(node.expression, node);
      printer.semicolon();
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printAssignmentPattern(printer: any, node: t.AssignmentPattern) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "AssignmentPattern";
    try {
      printer.print(node.left, node);
      if ((node.left as any).optional) printer.token("?");
      printer.print((node.left as any).typeAnnotation, node);
      printer.space();
      printer.token("=");
      printer.space();
      printer.print(node.right, node);
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printAssignmentExpression(
    printer: any,
    node: t.AssignmentExpression,
    parent: any,
  ) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "AssignmentExpression";
    try {
      const parens =
        printer.inForStatementInitCounter &&
        node.operator === "in" &&
        !this.needsParens(node, parent);

      if (parens) {
        printer.token("(");
      }

      printer.print(node.left, node);
      printer.space();
      if (node.operator === "in" || node.operator === "instanceof") {
        printer.word(node.operator);
      } else {
        printer.token(node.operator);
      }
      printer.space();
      printer.print(node.right, node);

      if (parens) {
        printer.token(")");
      }
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printBindExpression(printer: any, node: t.BindExpression) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "BindExpression";
    try {
      printer.print(node.object, node);
      printer.token("::");
      printer.print(node.callee, node);
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printMemberExpression(printer: any, node: t.MemberExpression) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "MemberExpression";
    try {
      printer.print(node.object, node);

      if (!node.computed && isMemberExpression(node.property)) {
        throw new TypeError(
          "Got a MemberExpression for MemberExpression property",
        );
      }

      let computed = node.computed;
      if (isLiteral(node.property) && typeof node.property.value === "number") {
        computed = true;
      }

      if (computed) {
        printer.token("[");
        printer.print(node.property, node);
        printer.token("]");
      } else {
        printer.token(".");
        printer.print(node.property, node);
      }
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printMetaProperty(printer: any, node: t.MetaProperty) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "MetaProperty";
    try {
      printer.print(node.meta, node);
      printer.token(".");
      printer.print(node.property, node);
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printPrivateName(printer: any, node: t.PrivateName) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "PrivateName";
    try {
      printer.token("#");
      printer.print(node.id, node);
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printV8IntrinsicIdentifier(printer: any, node: t.V8IntrinsicIdentifier) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "V8IntrinsicIdentifier";
    try {
      printer.token("%");
      printer.word(node.name);
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printModuleExpression(printer: any, node: t.ModuleExpression) {
    const previousPrinter = this._expressionPrinter;
    const previousType = this._lastExpressionType;
    this._expressionPrinter = printer;
    this._lastExpressionType = "ModuleExpression";
    try {
      printer.word("module");
      printer.space();
      printer.token("{");
      if (node.body.body.length === 0) {
        printer.token("}");
      } else {
        printer.newline();
        printer.printSequence(node.body.body, node, { indent: true });
        printer.rightBrace();
      }
    } finally {
      this._expressionPrinter = previousPrinter;
      this._lastExpressionType = previousType;
    }
  }

  printWithStatement(printer: any, node: t.WithStatement) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "WithStatement";
    try {
      printer.word("with");
      printer.space();
      printer.token("(");
      printer.print(node.object, node);
      printer.token(")");
      printer.printBlock(node);
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  getLastStatement(statement: any) {
    this._lastStatementKind = this._lastStatementKind || "IfStatement";
    if (!isStatement(statement.body)) return statement;
    return this.getLastStatement(statement.body);
  }

  printIfStatement(printer: any, node: t.IfStatement) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "IfStatement";
    try {
      printer.word("if");
      printer.space();
      printer.token("(");
      printer.print(node.test, node);
      printer.token(")");
      printer.space();

      const needsBlock =
        node.alternate && isIfStatement(this.getLastStatement(node.consequent));
      if (needsBlock) {
        printer.token("{");
        printer.newline();
        printer.indent();
      }

      printer.printAndIndentOnComments(node.consequent, node);

      if (needsBlock) {
        printer.dedent();
        printer.newline();
        printer.token("}");
      }

      if (node.alternate) {
        if (printer.endsWith(charCodes.rightCurlyBrace)) printer.space();
        printer.word("else");
        printer.space();
        printer.printAndIndentOnComments(node.alternate, node);
      }
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printForStatement(printer: any, node: t.ForStatement) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "ForStatement";
    try {
      printer.word("for");
      printer.space();
      printer.token("(");

      printer.inForStatementInitCounter++;
      printer.print(node.init, node);
      printer.inForStatementInitCounter--;
      printer.token(";");

      if (node.test) {
        printer.space();
        printer.print(node.test, node);
      }
      printer.token(";");

      if (node.update) {
        printer.space();
        printer.print(node.update, node);
      }

      printer.token(")");
      printer.printBlock(node);
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printWhileStatement(printer: any, node: t.WhileStatement) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "WhileStatement";
    try {
      printer.word("while");
      printer.space();
      printer.token("(");
      printer.print(node.test, node);
      printer.token(")");
      printer.printBlock(node);
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printForXStatement(printer: any, node: any, op: string) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = op === "of" ? "ForOfStatement" : "ForInStatement";
    try {
      printer.word("for");
      printer.space();
      if (op === "of" && node.await) {
        printer.word("await");
        printer.space();
      }
      printer.token("(");
      printer.print(node.left, node);
      printer.space();
      printer.word(op);
      printer.space();
      printer.print(node.right, node);
      printer.token(")");
      printer.printBlock(node);
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printForInStatement(printer: any, node: any) {
    this.printForXStatement(printer, node, "in");
  }

  printForOfStatement(printer: any, node: any) {
    this.printForXStatement(printer, node, "of");
  }

  printDoWhileStatement(printer: any, node: t.DoWhileStatement) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "DoWhileStatement";
    try {
      printer.word("do");
      printer.space();
      printer.print(node.body, node);
      printer.space();
      printer.word("while");
      printer.space();
      printer.token("(");
      printer.print(node.test, node);
      printer.token(")");
      printer.semicolon();
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printLabelStatement(printer: any, node: any, prefix: string, key = "label") {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = prefix;
    try {
      printer.word(prefix);
      const label = node[key];
      if (label) {
        printer.space();
        const isLabel = key == "label";
        const terminatorState = printer.startTerminatorless(isLabel);
        printer.print(label, node);
        printer.endTerminatorless(terminatorState);
      }
      printer.semicolon();
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printContinueStatement(printer: any, node: any) {
    this.printLabelStatement(printer, node, "continue");
  }

  printReturnStatement(printer: any, node: any) {
    this.printLabelStatement(printer, node, "return", "argument");
  }

  printBreakStatement(printer: any, node: any) {
    this.printLabelStatement(printer, node, "break");
  }

  printThrowStatement(printer: any, node: any) {
    this.printLabelStatement(printer, node, "throw", "argument");
  }

  printLabeledStatement(printer: any, node: t.LabeledStatement) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "LabeledStatement";
    try {
      printer.print(node.label, node);
      printer.token(":");
      printer.space();
      printer.print(node.body, node);
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printTryStatement(printer: any, node: t.TryStatement) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "TryStatement";
    try {
      printer.word("try");
      printer.space();
      printer.print(node.block, node);
      printer.space();

      if ((node as any).handlers) {
        printer.print((node as any).handlers[0], node);
      } else {
        printer.print(node.handler, node);
      }

      if (node.finalizer) {
        printer.space();
        printer.word("finally");
        printer.space();
        printer.print(node.finalizer, node);
      }
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printCatchClause(printer: any, node: t.CatchClause) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "CatchClause";
    try {
      printer.word("catch");
      printer.space();
      if (node.param) {
        printer.token("(");
        printer.print(node.param, node);
        printer.print(node.param.typeAnnotation, node);
        printer.token(")");
        printer.space();
      }
      printer.print(node.body, node);
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printSwitchStatement(printer: any, node: t.SwitchStatement) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "SwitchStatement";
    try {
      printer.word("switch");
      printer.space();
      printer.token("(");
      printer.print(node.discriminant, node);
      printer.token(")");
      printer.space();
      printer.token("{");

      printer.printSequence(node.cases, node, {
        indent: true,
        addNewlines(leading, cas) {
          if (!leading && node.cases[node.cases.length - 1] === cas) return -1;
        },
      });

      printer.token("}");
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printSwitchCase(printer: any, node: t.SwitchCase) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "SwitchCase";
    try {
      if (node.test) {
        printer.word("case");
        printer.space();
        printer.print(node.test, node);
        printer.token(":");
      } else {
        printer.word("default");
        printer.token(":");
      }

      if (node.consequent.length) {
        printer.newline();
        printer.printSequence(node.consequent, node, { indent: true });
      }
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printDebuggerStatement(printer: any) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "DebuggerStatement";
    try {
      printer.word("debugger");
      printer.semicolon();
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  variableDeclarationIndent(printer: any) {
    this._statementPrinter = printer;
    printer.token(",");
    printer.newline();
    if (printer.endsWith(charCodes.lineFeed)) {
      for (let i = 0; i < 4; i++) printer.space(true);
    }
  }

  constDeclarationIndent(printer: any) {
    this._statementPrinter = printer;
    printer.token(",");
    printer.newline();
    if (printer.endsWith(charCodes.lineFeed)) {
      for (let i = 0; i < 6; i++) printer.space(true);
    }
  }

  printVariableDeclaration(
    printer: any,
    node: t.VariableDeclaration,
    parent: t.Node,
  ) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "VariableDeclaration";
    try {
      if (node.declare) {
        printer.word("declare");
        printer.space();
      }

      printer.word(node.kind);
      printer.space();

      let hasInits = false;
      if (!isFor(parent)) {
        for (const declar of node.declarations) {
          if (declar.init) {
            hasInits = true;
          }
        }
      }

      let separator;
      if (hasInits) {
        const context = this;
        separator =
          node.kind === "const"
            ? function () {
                context.constDeclarationIndent(this);
              }
            : function () {
                context.variableDeclarationIndent(this);
              };
      }

      printer.printList(node.declarations, node, { separator });

      if (isFor(parent)) {
        if (isForStatement(parent)) {
          if (parent.init === node) return;
        } else {
          if ((parent as any).left === node) return;
        }
      }

      printer.semicolon();
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printVariableDeclarator(printer: any, node: t.VariableDeclarator) {
    const previousPrinter = this._statementPrinter;
    const previousKind = this._lastStatementKind;
    this._statementPrinter = printer;
    this._lastStatementKind = "VariableDeclarator";
    try {
      printer.print(node.id, node);
      if (node.definite) printer.token("!");
      printer.print((node.id as any).typeAnnotation, node);
      if (node.init) {
        printer.space();
        printer.token("=");
        printer.space();
        printer.print(node.init, node);
      }
    } finally {
      this._statementPrinter = previousPrinter;
      this._lastStatementKind = previousKind;
    }
  }

  printParams(printer: any, node: any) {
    const previousPrinter = this._functionPrinter;
    const previousKind = this._lastFunctionKind;
    this._functionPrinter = printer;
    this._lastFunctionKind = "params";
    try {
      printer.print(node.typeParameters, node);
      printer.token("(");
      this.printParameters(printer, node.params, node);
      printer.token(")");
      printer.print(node.returnType, node);
    } finally {
      this._functionPrinter = previousPrinter;
      this._lastFunctionKind = previousKind;
    }
  }

  printParameters(printer: any, parameters: any, parent: any) {
    this._functionPrinter = printer;
    this._lastFunctionKind = "parameters";
    for (let i = 0; i < parameters.length; i++) {
      this.printParam(printer, parameters[i], parent);
      if (i < parameters.length - 1) {
        printer.token(",");
        printer.space();
      }
    }
  }

  printParam(printer: any, parameter: any, parent?: any) {
    this._functionPrinter = printer;
    this._lastFunctionKind = "param";
    printer.printJoin(parameter.decorators, parameter);
    printer.print(parameter, parent);
    if (parameter.optional) printer.token("?");
    printer.print(parameter.typeAnnotation, parameter);
  }

  printMethodHead(printer: any, node: any) {
    const previousPrinter = this._functionPrinter;
    const previousKind = this._lastFunctionKind;
    this._functionPrinter = printer;
    this._lastFunctionKind = "methodHead";
    try {
      const kind = node.kind;
      const key = node.key;

      if (kind === "get" || kind === "set") {
        printer.word(kind);
        printer.space();
      }

      if (node.async) {
        printer._catchUp("start", key.loc);
        printer.word("async");
        printer.space();
      }

      if (kind === "method" || kind === "init") {
        if (node.generator) {
          printer.token("*");
        }
      }

      if (node.computed) {
        printer.token("[");
        printer.print(key, node);
        printer.token("]");
      } else {
        printer.print(key, node);
      }

      if (node.optional) {
        printer.token("?");
      }

      this.printParams(printer, node);
    } finally {
      this._functionPrinter = previousPrinter;
      this._lastFunctionKind = previousKind;
    }
  }

  printPredicate(printer: any, node: any) {
    this._functionPrinter = printer;
    this._lastFunctionKind = "predicate";
    if (node.predicate) {
      if (!node.returnType) {
        printer.token(":");
      }
      printer.space();
      printer.print(node.predicate, node);
    }
  }

  printFunctionHead(printer: any, node: any) {
    const previousPrinter = this._functionPrinter;
    const previousKind = this._lastFunctionKind;
    this._functionPrinter = printer;
    this._lastFunctionKind = "functionHead";
    try {
      if (node.async) {
        printer.word("async");
        printer.space();
      }
      printer.word("function");
      if (node.generator) printer.token("*");
      printer.printInnerComments(node);

      printer.space();
      if (node.id) {
        printer.print(node.id, node);
      }

      this.printParams(printer, node);
      this.printPredicate(printer, node);
    } finally {
      this._functionPrinter = previousPrinter;
      this._lastFunctionKind = previousKind;
    }
  }

  printFunctionExpression(printer: any, node: t.FunctionExpression) {
    const previousPrinter = this._functionPrinter;
    const previousKind = this._lastFunctionKind;
    this._functionPrinter = printer;
    this._lastFunctionKind = "FunctionExpression";
    try {
      this.printFunctionHead(printer, node);
      printer.space();
      printer.print(node.body, node);
    } finally {
      this._functionPrinter = previousPrinter;
      this._lastFunctionKind = previousKind;
    }
  }

  hasTypesOrComments(
    node: t.ArrowFunctionExpression,
    param: t.Identifier,
  ): boolean {
    this._lastFunctionKind = this._lastFunctionKind || "ArrowFunctionExpression";
    return !!(
      node.typeParameters ||
      node.returnType ||
      node.predicate ||
      param.typeAnnotation ||
      param.optional ||
      param.leadingComments?.length ||
      param.trailingComments?.length
    );
  }

  printArrowFunctionExpression(printer: any, node: t.ArrowFunctionExpression) {
    const previousPrinter = this._functionPrinter;
    const previousKind = this._lastFunctionKind;
    this._functionPrinter = printer;
    this._lastFunctionKind = "ArrowFunctionExpression";
    try {
      if (node.async) {
        printer.word("async");
        printer.space();
      }

      const firstParam = node.params[0];

      if (
        !printer.format.retainLines &&
        !printer.format.auxiliaryCommentBefore &&
        !printer.format.auxiliaryCommentAfter &&
        node.params.length === 1 &&
        isIdentifier(firstParam) &&
        !this.hasTypesOrComments(node, firstParam)
      ) {
        printer.print(firstParam, node);
      } else {
        this.printParams(printer, node);
      }

      this.printPredicate(printer, node);
      printer.space();
      printer.token("=>");
      printer.space();
      printer.print(node.body, node);
    } finally {
      this._functionPrinter = previousPrinter;
      this._lastFunctionKind = previousKind;
    }
  }

  maybeAddParen(printer: any, str: string): void {
    this._terminatorPrinter = printer;
    const parenPushNewlineState = printer._parenPushNewlineState;
    this._parenPushNewlineState = parenPushNewlineState;
    if (!parenPushNewlineState) return;

    let i;
    for (i = 0; i < str.length && str[i] === " "; i++) continue;
    if (i === str.length) {
      return;
    }

    const cha = str[i];
    if (cha !== "\n") {
      if (cha !== "/" || i + 1 === str.length) {
        this._parenPushNewlineState = null;
        printer._parenPushNewlineState = null;
        return;
      }

      const chaPost = str[i + 1];

      if (chaPost === "*") {
        if (this._pureAnnotationRe.test(str.slice(i + 2, str.length - 2))) {
          return;
        }
      } else if (chaPost !== "/") {
        this._parenPushNewlineState = null;
        printer._parenPushNewlineState = null;
        return;
      }
    }

    printer.token("(");
    printer.indent();
    parenPushNewlineState.printed = true;
  }

  startTerminatorless(printer: any, isLabel: boolean = false) {
    this._terminatorPrinter = printer;
    if (isLabel) {
      this._noLineTerminator = true;
      printer._noLineTerminator = true;
      return null;
    } else {
      this._parenPushNewlineState = {
        printed: false,
      };
      return (printer._parenPushNewlineState = this._parenPushNewlineState);
    }
  }

  endTerminatorless(printer: any, state?: any) {
    this._terminatorPrinter = printer;
    this._noLineTerminator = false;
    printer._noLineTerminator = false;
    if (state?.printed) {
      printer.dedent();
      printer.newline();
      printer.token(")");
    }
  }
}

export const generatorContext = new GeneratorContext();

export function NullableTypeAnnotation(node: any, parent: any): boolean {
  return generatorContext.nullableTypeAnnotation(node, parent);
}

export function FunctionTypeAnnotation(
  node: any,
  parent: any,
  printStack: Array<any>,
): boolean {
  return generatorContext.functionTypeAnnotation(node, parent, printStack);
}

